async fn request_context_middleware(
    mut req: axum::http::Request<axum::body::Body>,
    next: middleware::Next,
) -> Response {
    let headers = req.headers();
    let request_id = headers
        .get(REQUEST_ID_HEADER)
        .and_then(|v| v.to_str().ok())
        .map(|v| v.trim().to_string())
        .filter(|v| !v.is_empty())
        .unwrap_or_else(generate_trace_id);
    let trace_id = headers
        .get(TRACE_ID_HEADER)
        .and_then(|v| v.to_str().ok())
        .map(|v| v.trim().to_string())
        .filter(|v| !v.is_empty())
        .unwrap_or_else(|| request_id.clone());

    let ip = extract_ip(headers);
    let user_agent = headers
        .get(axum::http::header::USER_AGENT)
        .and_then(|v| v.to_str().ok())
        .map(|v| v.to_string());

    req.extensions_mut().insert(RequestContext {
        request_id: request_id.clone(),
        trace_id: trace_id.clone(),
        ip,
        user_agent,
    });

    let mut response = next.run(req).await;
    if let Ok(value) = HeaderValue::from_str(&request_id) {
        response.headers_mut().insert(REQUEST_ID_HEADER, value);
    }
    if let Ok(value) = HeaderValue::from_str(&trace_id) {
        response.headers_mut().insert(TRACE_ID_HEADER, value);
    }
    response
}

fn extract_ip(headers: &HeaderMap) -> Option<String> {
    if let Some(value) = headers.get("x-forwarded-for").and_then(|v| v.to_str().ok()) {
        if let Some((first, _)) = value.split_once(',') {
            let ip = first.trim();
            if !ip.is_empty() {
                return Some(ip.to_string());
            }
        } else if !value.trim().is_empty() {
            return Some(value.trim().to_string());
        }
    }
    headers
        .get("x-real-ip")
        .and_then(|v| v.to_str().ok())
        .map(|v| v.trim().to_string())
        .filter(|v| !v.is_empty())
}

async fn auth_middleware(
    State(state): State<AppState>,
    mut req: axum::http::Request<axum::body::Body>,
    next: middleware::Next,
) -> impl IntoResponse {
    let path = req.uri().path().to_string();
    if path == "/healthz" || path == "/auth/login" || path.starts_with("/v1/print-agent") {
        return next.run(req).await;
    }

    let headers = req.headers();
    let Some(auth) = headers
        .get(axum::http::header::AUTHORIZATION)
        .and_then(|v| v.to_str().ok())
    else {
        return (StatusCode::UNAUTHORIZED, "missing Authorization").into_response();
    };
    let Some(token) = auth
        .strip_prefix("Bearer ")
        .or_else(|| auth.strip_prefix("bearer "))
    else {
        return (StatusCode::UNAUTHORIZED, "invalid Authorization scheme").into_response();
    };

    match state.jwt.decode(token) {
        Ok(claims) => {
            let tenant_id = match TenantId::from_str(&claims.tenant_id) {
                Ok(v) => v,
                Err(_) => {
                    return (StatusCode::UNAUTHORIZED, "bad tenant_id in token").into_response()
                }
            };
            let user_id = match UserId::from_str(&claims.sub) {
                Ok(v) => v,
                Err(_) => return (StatusCode::UNAUTHORIZED, "bad sub in token").into_response(),
            };
            if !claims.is_admin {
                if let Some(path_tenant_id) = tenant_id_from_path(&path) {
                    if path_tenant_id != tenant_id {
                        return forbidden("tenant mismatch").into_response();
                    }
                }
            }
            let perms = normalize_permissions(claims.perms);
            let (shop_ids, warehouse_ids, merchant_ids, organization_ids) = if claims.is_admin {
                (Vec::new(), Vec::new(), Vec::new(), Vec::new())
            } else {
                let scopes_repo = DataScopesRepo::new(state.db.pool());
                match scopes_repo.list_user_scopes(tenant_id, user_id).await {
                    Ok(scopes) => (
                        scopes.shop_ids,
                        scopes.warehouse_ids,
                        scopes.merchant_ids,
                        scopes.organization_ids,
                    ),
                    Err(err) => {
                        warn!(tenant_id=%tenant_id, user_id=%user_id, error=%err, "failed to load data scopes");
                        (Vec::new(), Vec::new(), Vec::new(), Vec::new())
                    }
                }
            };
            req.extensions_mut().insert(AuthContext {
                tenant_id,
                user_id,
                perms,
                is_admin: claims.is_admin,
                shop_ids,
                warehouse_ids,
                merchant_ids,
                organization_ids,
            });
            next.run(req).await
        }
        Err(e) => {
            warn!(error = %e, "jwt decode failed");
            (StatusCode::UNAUTHORIZED, "invalid token").into_response()
        }
    }
}

async fn device_auth_middleware(
    State(state): State<AppState>,
    mut req: axum::http::Request<axum::body::Body>,
    next: middleware::Next,
) -> impl IntoResponse {
    let headers = req.headers();
    let token = headers
        .get("x-device-token")
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let Some(token) = token else {
        return (StatusCode::UNAUTHORIZED, "missing device token").into_response();
    };

    let repo = PrintDevicesRepoCore::new(state.db.pool());
    let device = match repo.get_device_by_token(token).await {
        Ok(Some(device)) => device,
        Ok(None) => return (StatusCode::UNAUTHORIZED, "invalid device token").into_response(),
        Err(err) => {
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("device lookup failed: {err}"),
            )
                .into_response()
        }
    };

    if device.status != "ACTIVE" {
        return (StatusCode::FORBIDDEN, "device inactive").into_response();
    }

    req.extensions_mut().insert(DeviceAuthContext {
        tenant_id: device.tenant_id,
        device_id: device.device_id,
        fingerprint: device.fingerprint,
        name: device.name,
    });
    next.run(req).await
}

async fn read_only_middleware(
    State(state): State<AppState>,
    req: axum::http::Request<axum::body::Body>,
    next: middleware::Next,
) -> impl IntoResponse {
    if !is_write_method(req.method()) {
        return next.run(req).await;
    }

    let path = req.uri().path();
    if path == "/healthz" || path == "/auth/login" {
        return next.run(req).await;
    }

    let Some(tenant_id) = tenant_id_from_path(path) else {
        return next.run(req).await;
    };

    let read_only = match read_only_enabled(&state, tenant_id, None).await {
        Ok(v) => v,
        Err(resp) => {
            warn!(
                tenant_id = %tenant_id,
                status = %resp.0,
                "read-only check failed; allowing request"
            );
            return next.run(req).await;
        }
    };
    if read_only {
        return read_only_forbidden().into_response();
    }

    next.run(req).await
}

async fn healthz(State(state): State<AppState>) -> impl IntoResponse {
    // Deep health check: DB ping
    let ok = sqlx::query_scalar::<_, i64>("select 1::bigint")
        .fetch_one(state.db.pool())
        .await
        .is_ok();

    if ok {
        (StatusCode::OK, "ok")
    } else {
        (StatusCode::SERVICE_UNAVAILABLE, "db not ready")
    }
}

async fn login(State(state): State<AppState>, Json(req): Json<LoginRequest>) -> impl IntoResponse {
    let tenant_id = match TenantId::from_str(&req.tenant_id) {
        Ok(v) => v,
        Err(_) => return (StatusCode::BAD_REQUEST, "bad tenant_id").into_response(),
    };

    let auth_repo = AuthRepo::new(state.db.pool());
    let user = match auth_repo.find_user_by_email(tenant_id, &req.email).await {
        Ok(Some(v)) => v,
        Ok(None) => return (StatusCode::UNAUTHORIZED, "invalid credentials").into_response(),
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    if user.status != "ACTIVE" {
        return (StatusCode::UNAUTHORIZED, "user disabled").into_response();
    }

    let parsed_hash = match argon2::PasswordHash::new(&user.password_hash) {
        Ok(v) => v,
        Err(_) => return (StatusCode::UNAUTHORIZED, "invalid credentials").into_response(),
    };

    if argon2::Argon2::default()
        .verify_password(req.password.as_bytes(), &parsed_hash)
        .is_err()
    {
        return (StatusCode::UNAUTHORIZED, "invalid credentials").into_response();
    }

    let perms = match auth_repo.list_permissions(tenant_id, user.user_id).await {
        Ok(v) => v,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    let now = Utc::now().timestamp() as usize;
    let exp = now + 3600; // 1 hour
    let claims = Claims {
        sub: user.user_id.to_string(),
        tenant_id: tenant_id.to_string(),
        perms,
        is_admin: false,
        iat: now,
        exp,
    };

    let token = match state.jwt.encode(&claims) {
        Ok(v) => v,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    Json(LoginResponse {
        access_token: token,
        token_type: "Bearer",
        expires_in: 3600,
    })
    .into_response()
}

async fn get_current_user(
    State(state): State<AppState>,
    Extension(ctx): Extension<AuthContext>,
) -> impl IntoResponse {
    let repo = RbacRepo::new(state.db.pool());
    let user = match repo.get_user(ctx.tenant_id, ctx.user_id).await {
        Ok(Some(v)) => v,
        Ok(None) => {
            return error_response(StatusCode::UNAUTHORIZED, "unauthorized", "user missing")
                .into_response()
        }
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    let roles = match repo.list_user_roles(ctx.tenant_id, ctx.user_id).await {
        Ok(v) => v,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    let response = CurrentUserResponse {
        user,
        roles,
        permissions: ctx.perms.clone(),
        data_scopes: DataScopeResponse {
            shop_ids: ctx.shop_ids.iter().map(|id| id.to_string()).collect(),
            warehouse_ids: ctx.warehouse_ids.iter().map(|id| id.to_string()).collect(),
            merchant_ids: ctx.merchant_ids.iter().map(|id| id.to_string()).collect(),
            organization_ids: ctx.organization_ids.iter().map(|id| id.to_string()).collect(),
        },
    };

    (StatusCode::OK, Json(response)).into_response()
}

async fn update_current_user_profile(
    State(state): State<AppState>,
    Extension(ctx): Extension<AuthContext>,
    Extension(req_ctx): Extension<RequestContext>,
    Json(req): Json<CurrentUserUpdateRequest>,
) -> impl IntoResponse {
    let email = match req.email.as_deref().map(str::trim) {
        Some(value) if !value.is_empty() => value.to_string(),
        _ => return bad_request("email required").into_response(),
    };

    let repo = RbacRepo::new(state.db.pool());
    let before = match repo.get_user(ctx.tenant_id, ctx.user_id).await {
        Ok(Some(user)) => serde_json::to_value(user).ok(),
        Ok(None) => return not_found("user not found").into_response(),
        Err(_) => None,
    };

    let user = match repo
        .update_user(
            ctx.tenant_id,
            ctx.user_id,
            UserUpdate {
                email: Some(email),
                password_hash: None,
                status: None,
            },
        )
        .await
    {
        Ok(Some(user)) => user,
        Ok(None) => return not_found("user not found").into_response(),
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    record_audit_log(
        &state,
        &ctx,
        &req_ctx,
        "SYS.USER.PROFILE.UPDATE",
        "user",
        Some(user.user_id.to_string()),
        before,
        Some(serde_json::to_value(&user).unwrap_or(Value::Null)),
    )
    .await;

    (StatusCode::OK, Json(user)).into_response()
}

async fn update_current_user_password(
    State(state): State<AppState>,
    Extension(ctx): Extension<AuthContext>,
    Extension(req_ctx): Extension<RequestContext>,
    Json(req): Json<CurrentUserPasswordRequest>,
) -> impl IntoResponse {
    let current_password = req.current_password.trim();
    let new_password = req.new_password.trim();
    if current_password.is_empty() {
        return bad_request("current_password required").into_response();
    }
    if new_password.is_empty() {
        return bad_request("new_password required").into_response();
    }

    let auth_repo = AuthRepo::new(state.db.pool());
    let user_row = match auth_repo.get_user_by_id(ctx.tenant_id, ctx.user_id).await {
        Ok(Some(user)) => user,
        Ok(None) => return not_found("user not found").into_response(),
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    let parsed_hash = match argon2::PasswordHash::new(&user_row.password_hash) {
        Ok(v) => v,
        Err(_) => return (StatusCode::UNAUTHORIZED, "invalid credentials").into_response(),
    };
    if argon2::Argon2::default()
        .verify_password(current_password.as_bytes(), &parsed_hash)
        .is_err()
    {
        return (StatusCode::UNAUTHORIZED, "invalid credentials").into_response();
    }

    let salt = argon2::password_hash::SaltString::generate(&mut rand::thread_rng());
    let hash = match argon2::Argon2::default().hash_password(new_password.as_bytes(), &salt) {
        Ok(v) => v.to_string(),
        Err(_) => return (StatusCode::INTERNAL_SERVER_ERROR, "hash failed").into_response(),
    };

    let repo = RbacRepo::new(state.db.pool());
    let before = match repo.get_user(ctx.tenant_id, ctx.user_id).await {
        Ok(Some(user)) => serde_json::to_value(user).ok(),
        Ok(None) => return not_found("user not found").into_response(),
        Err(_) => None,
    };

    let user = match repo
        .update_user(
            ctx.tenant_id,
            ctx.user_id,
            UserUpdate {
                email: None,
                password_hash: Some(hash),
                status: None,
            },
        )
        .await
    {
        Ok(Some(user)) => user,
        Ok(None) => return not_found("user not found").into_response(),
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    record_audit_log(
        &state,
        &ctx,
        &req_ctx,
        "SYS.USER.PASSWORD.UPDATE",
        "user",
        Some(user.user_id.to_string()),
        before,
        Some(serde_json::to_value(&user).unwrap_or(Value::Null)),
    )
    .await;

    (StatusCode::OK, Json(user)).into_response()
}

#[allow(dead_code)]
async fn export_order_review_hits(
    State(state): State<AppState>,
    Path(tenant_id): Path<String>,
    Extension(ctx): Extension<AuthContext>,
    Json(req): Json<OrderReviewHitsExportRequest>,
) -> impl IntoResponse {
    let tenant_id = match TenantId::from_str(&tenant_id) {
        Ok(v) => v,
        Err(_) => return bad_request("bad tenant_id").into_response(),
    };
    if let Err(resp) = ensure_tenant_access(&ctx, tenant_id) {
        return resp.into_response();
    }
    if let Err(resp) = ensure_permission(&ctx, "exports.write") {
        return resp.into_response();
    }
    if req.order_ids.is_empty() {
        return bad_request("order_ids required").into_response();
    }

    let repo = ExportJobsRepo::new(state.db.pool());
    let job = match repo
        .create_job(ExportJobCreateInput {
            tenant_id,
            job_type: "ORDER_REVIEW_HITS_EXPORT".to_string(),
            params_json: serde_json::json!({ "order_ids": req.order_ids }),
        })
        .await
    {
        Ok(v) => v,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    let orders_repo = OrdersRepo::new(state.db.pool());
    let mut rows: Vec<Vec<String>> = Vec::new();
    rows.push(vec![
        "订单ID".to_string(),
        "平台订单号".to_string(),
        "规则名称".to_string(),
        "动作".to_string(),
        "是否命中".to_string(),
        "说明".to_string(),
        "时间".to_string(),
    ]);

    for raw_id in &job.params_json["order_ids"]
        .as_array()
        .cloned()
        .unwrap_or_default()
    {
        let Some(raw) = raw_id.as_str() else {
            continue;
        };
        let order_id = match OrderId::from_str(raw) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let detail = match orders_repo.get_order_detail(tenant_id, order_id).await {
            Ok(Some(v)) => v,
            Ok(None) => continue,
            Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
        };
        for hit in detail.review_hits {
            rows.push(vec![
                order_id.to_string(),
                detail.order.platform_order_id.clone(),
                hit.rule_name,
                hit.action,
                if hit.hit { "命中" } else { "未命中" }.to_string(),
                hit.message,
                hit.created_at.to_rfc3339(),
            ]);
        }
    }

    let csv = rows
        .into_iter()
        .map(|row| {
            row.into_iter()
                .map(|cell| format!("\"{}\"", cell.replace('"', "\"\"")))
                .collect::<Vec<_>>()
                .join(",")
        })
        .collect::<Vec<_>>()
        .join("\n");

    let file_path = export_job_file_path(tenant_id, job.job_id);
    if let Some(parent) = file_path.parent() {
        if let Err(err) = tokio::fs::create_dir_all(parent).await {
            return (StatusCode::INTERNAL_SERVER_ERROR, format!("{err}")).into_response();
        }
    }
    if let Err(err) = tokio::fs::write(&file_path, format!("\u{FEFF}{csv}")).await {
        return (StatusCode::INTERNAL_SERVER_ERROR, format!("{err}")).into_response();
    }

    let output_url = Some(format!("/exports/jobs/{}/file", job.job_id));
    let updated = match repo
        .update_job(
            tenant_id,
            job.job_id,
            ExportJobUpdate {
                status: Some("DONE".to_string()),
                output_url: Some(output_url.clone()),
                progress: Some(100),
                last_error: None,
                params_json: None,
            },
        )
        .await
    {
        Ok(Some(v)) => v,
        Ok(None) => job,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    let audit_repo = AuditLogsRepo::new(state.db.pool());
    let _ = audit_repo
        .insert(AuditLogCreate {
            tenant_id,
            user_id: Some(ctx.user_id),
            action: "ORDER.REVIEW_HITS_EXPORT".to_string(),
            entity_type: "EXPORT_JOB".to_string(),
            entity_id: Some(updated.job_id.to_string()),
            before_json: None,
            after_json: Some(serde_json::json!({ "output_url": output_url })),
            ip: None,
            ua: None,
        })
        .await;

    (StatusCode::OK, Json(export_job_response(updated))).into_response()
}

