async fn update_user_data_scopes(
    State(state): State<AppState>,
    Path((tenant_id, user_id)): Path<(String, String)>,
    Extension(ctx): Extension<AuthContext>,
    Extension(req_ctx): Extension<RequestContext>,
    Json(req): Json<DataScopeUpdateRequest>,
) -> impl IntoResponse {
    let tenant_id = match TenantId::from_str(&tenant_id) {
        Ok(v) => v,
        Err(_) => return bad_request("bad tenant_id").into_response(),
    };
    if let Err(resp) = ensure_tenant_access(&ctx, tenant_id) {
        return resp.into_response();
    }
    if let Err(resp) = ensure_permission(&ctx, PermissionCode::SysUserWrite.as_str()) {
        return resp.into_response();
    }
    let user_id = match UserId::from_str(&user_id) {
        Ok(v) => v,
        Err(_) => return bad_request("bad user_id").into_response(),
    };

    let shop_ids = match parse_shop_ids(&req.shop_ids) {
        Ok(v) => v,
        Err(resp) => return resp.into_response(),
    };
    let warehouse_ids = match parse_uuid_list(&req.warehouse_ids) {
        Ok(v) => v,
        Err(resp) => return resp.into_response(),
    };
    let merchant_ids = match parse_uuid_list(&req.merchant_ids) {
        Ok(v) => v,
        Err(resp) => return resp.into_response(),
    };
    let organization_ids = match parse_uuid_list(&req.organization_ids) {
        Ok(v) => v,
        Err(resp) => return resp.into_response(),
    };

    if let Err(resp) = ensure_shop_scope_subset(&ctx, &shop_ids) {
        return resp.into_response();
    }
    if let Err(resp) =
        ensure_uuid_scope_subset(&ctx, &merchant_ids, &ctx.merchant_ids, "merchant")
    {
        return resp.into_response();
    }
    if let Err(resp) =
        ensure_uuid_scope_subset(&ctx, &organization_ids, &ctx.organization_ids, "organization")
    {
        return resp.into_response();
    }

    let repo = DataScopesRepo::new(state.db.pool());
    if let Err(e) = repo.replace_user_shops(tenant_id, user_id, &shop_ids).await {
        return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response();
    }
    if let Err(e) = repo
        .replace_user_warehouses(tenant_id, user_id, &warehouse_ids)
        .await
    {
        return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response();
    }
    if let Err(e) = repo
        .replace_user_merchants(tenant_id, user_id, &merchant_ids)
        .await
    {
        return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response();
    }
    if let Err(e) = repo
        .replace_user_organizations(tenant_id, user_id, &organization_ids)
        .await
    {
        return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response();
    }

    record_audit_log(
        &state,
        &ctx,
        &req_ctx,
        "SYS.USER.DATA_SCOPE",
        "user",
        Some(user_id.to_string()),
        None,
        Some(serde_json::json!({
        "shop_ids": req.shop_ids,
        "warehouse_ids": req.warehouse_ids,
        "merchant_ids": req.merchant_ids,
        "organization_ids": req.organization_ids,
        })),
    )
    .await;

    (StatusCode::OK, Json("ok")).into_response()
}

async fn list_audit_logs(
    State(state): State<AppState>,
    Path(tenant_id): Path<String>,
    Query(query): Query<AuditLogListQuery>,
    Extension(ctx): Extension<AuthContext>,
) -> impl IntoResponse {
    let tenant_id = match TenantId::from_str(&tenant_id) {
        Ok(v) => v,
        Err(_) => return bad_request("bad tenant_id").into_response(),
    };
    if let Err(resp) = ensure_tenant_access(&ctx, tenant_id) {
        return resp.into_response();
    }
    if let Err(resp) = ensure_permission(&ctx, PermissionCode::SysAuditRead.as_str()) {
        return resp.into_response();
    }

    let cursor = match query.cursor.as_deref() {
        Some(raw) => match AuditLogCursor::decode(raw) {
            Ok(v) => Some(v),
            Err(_) => return bad_request("bad cursor").into_response(),
        },
        None => None,
    };
    let created_from = match query.created_from.as_deref() {
        Some(raw) => match DateTime::parse_from_rfc3339(raw) {
            Ok(v) => Some(v.with_timezone(&Utc)),
            Err(_) => return bad_request("bad created_from").into_response(),
        },
        None => None,
    };
    let created_to = match query.created_to.as_deref() {
        Some(raw) => match DateTime::parse_from_rfc3339(raw) {
            Ok(v) => Some(v.with_timezone(&Utc)),
            Err(_) => return bad_request("bad created_to").into_response(),
        },
        None => None,
    };
    let user_id = match query.user_id.as_deref() {
        Some(raw) => match UserId::from_str(raw) {
            Ok(v) => Some(v),
            Err(_) => return bad_request("bad user_id").into_response(),
        },
        None => None,
    };
    let limit = query.limit.unwrap_or(50).clamp(1, 200);

    let repo = AuditLogsRepo::new(state.db.pool());
    let result = match repo
        .list_logs(
            tenant_id,
            AuditLogListFilters {
                action: query.action.clone(),
                entity_type: query.entity_type.clone(),
                entity_id: query.entity_id.clone(),
                user_id,
                created_from,
                created_to,
                cursor,
                limit,
            },
        )
        .await
    {
        Ok(v) => v,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response(),
    };

    let response = ListResponse {
        data: result.items,
        next_cursor: result.next_cursor.map(|c| c.encode()),
    };
    (StatusCode::OK, Json(response)).into_response()
}

