fn normalize_permissions(perms: Vec<String>) -> Vec<String> {
    perms
        .into_iter()
        .map(|perm| normalize_permission_code(&perm))
        .collect()
}

fn parse_role_ids(role_ids: &[String]) -> Result<Vec<RoleId>, (StatusCode, Json<ErrorResponse>)> {
    let mut ids = Vec::with_capacity(role_ids.len());
    for raw in role_ids {
        match RoleId::from_str(raw) {
            Ok(id) => ids.push(id),
            Err(_) => return Err(bad_request("bad role_id")),
        }
    }
    Ok(ids)
}

fn parse_shop_ids(shop_ids: &[String]) -> Result<Vec<ShopId>, (StatusCode, Json<ErrorResponse>)> {
    let mut ids = Vec::with_capacity(shop_ids.len());
    for raw in shop_ids {
        match ShopId::from_str(raw) {
            Ok(id) => ids.push(id),
            Err(_) => return Err(bad_request("bad shop_id")),
        }
    }
    Ok(ids)
}

fn parse_uuid_list(ids: &[String]) -> Result<Vec<uuid::Uuid>, (StatusCode, Json<ErrorResponse>)> {
    let mut values = Vec::with_capacity(ids.len());
    for raw in ids {
        match uuid::Uuid::parse_str(raw) {
            Ok(id) => values.push(id),
            Err(_) => return Err(bad_request("bad uuid")),
        }
    }
    Ok(values)
}

fn parse_uuid_list_optional(
    ids: Option<&[String]>,
) -> Result<Option<Vec<uuid::Uuid>>, (StatusCode, Json<ErrorResponse>)> {
    let Some(ids) = ids else {
        return Ok(None);
    };
    let parsed = parse_uuid_list(ids)?;
    if parsed.is_empty() {
        Ok(None)
    } else {
        Ok(Some(parsed))
    }
}

fn parse_shop_ids_csv(
    raw: Option<&str>,
) -> Result<Option<Vec<ShopId>>, (StatusCode, Json<ErrorResponse>)> {
    let Some(raw) = raw else {
        return Ok(None);
    };
    let ids: Vec<String> = raw
        .split(',')
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
        .map(|value| value.to_string())
        .collect();
    if ids.is_empty() {
        return Ok(None);
    }
    parse_shop_ids(&ids).map(Some)
}

fn parse_shop_ids_optional(
    shop_ids: Option<&[String]>,
) -> Result<Option<Vec<ShopId>>, (StatusCode, Json<ErrorResponse>)> {
    let Some(shop_ids) = shop_ids else {
        return Ok(None);
    };
    let parsed = parse_shop_ids(shop_ids)?;
    if parsed.is_empty() {
        Ok(None)
    } else {
        Ok(Some(parsed))
    }
}

fn parse_platform_optional(
    raw: Option<&str>,
) -> Result<Option<Platform>, (StatusCode, Json<ErrorResponse>)> {
    let Some(raw) = raw else {
        return Ok(None);
    };
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }
    match Platform::from_str(trimmed) {
        Ok(v) => Ok(Some(v)),
        Err(_) => Err(bad_request("bad platform")),
    }
}

fn normalize_optional_string(input: Option<String>) -> Option<String> {
    input.and_then(|value| {
        let trimmed = value.trim();
        if trimmed.is_empty() {
            None
        } else {
            Some(trimmed.to_string())
        }
    })
}

fn parse_datetime_optional(
    raw: Option<&str>,
    field: &str,
) -> Result<Option<DateTime<Utc>>, (StatusCode, Json<ErrorResponse>)> {
    let Some(raw) = raw else {
        return Ok(None);
    };
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }
    if let Ok(value) = DateTime::parse_from_rfc3339(trimmed) {
        return Ok(Some(value.with_timezone(&Utc)));
    }
    if let Ok(date) = NaiveDate::parse_from_str(trimmed, "%Y-%m-%d") {
        let dt = date.and_hms_opt(0, 0, 0).unwrap();
        return Ok(Some(DateTime::<Utc>::from_naive_utc_and_offset(dt, Utc)));
    }
    Err(bad_request(&format!("bad {field}")))
}

fn parse_date_optional(
    raw: Option<&str>,
    field: &str,
) -> Result<Option<NaiveDate>, (StatusCode, Json<ErrorResponse>)> {
    let Some(raw) = raw else {
        return Ok(None);
    };
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }
    if let Ok(date) = NaiveDate::parse_from_str(trimmed, "%Y-%m-%d") {
        return Ok(Some(date));
    }
    if let Ok(value) = DateTime::parse_from_rfc3339(trimmed) {
        return Ok(Some(value.date_naive()));
    }
    Err(bad_request(&format!("bad {field}")))
}

fn parse_datetime_best_effort(raw: Option<&str>) -> Option<DateTime<Utc>> {
    let raw = raw?;
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return None;
    }
    if let Ok(value) = DateTime::parse_from_rfc3339(trimmed) {
        return Some(value.with_timezone(&Utc));
    }
    if let Ok(date) = NaiveDate::parse_from_str(trimmed, "%Y-%m-%d") {
        let dt = date.and_hms_opt(0, 0, 0).unwrap();
        return Some(DateTime::<Utc>::from_naive_utc_and_offset(dt, Utc));
    }
    None
}

fn dedup_uuid_list(mut items: Vec<uuid::Uuid>) -> Vec<uuid::Uuid> {
    items.sort();
    items.dedup();
    items
}

#[derive(Debug)]
struct AutoMatchSummary {
    total_count: i32,
    success_count: i32,
    failure_count: i32,
    failures: Vec<ShopProductMatchFailure>,
}

#[derive(Debug, Clone)]
#[allow(dead_code)]
struct MatchedSku {
    sku_id: uuid::Uuid,
    sku_code: String,
    name: Option<String>,
    barcode: Option<String>,
    spec: Value,
}

async fn auto_match_sku_views(
    pool: &PgPool,
    tenant_id: TenantId,
    views: &[ShopProductSkuView],
) -> anyhow::Result<AutoMatchSummary> {
    let mapping_repo = ChannelSkuMappingsRepo::new(pool);
    let mut total_count = 0;
    let mut success_count = 0;
    let mut failure_count = 0;
    let mut failures = Vec::new();

    for view in views {
        total_count += 1;
        if view.mapping_id.is_some() {
            if view
                .match_source
                .as_deref()
                .map(|value| value.eq_ignore_ascii_case("MANUAL"))
                .unwrap_or(false)
            {
                failure_count += 1;
                failures.push(ShopProductMatchFailure {
                    sku_record_id: view.sku_record_id,
                    platform_sku_id: view.platform_sku_id.clone(),
                    merchant_sku_code: view.merchant_sku_code.clone(),
                    reason: "已存在手动匹配".to_string(),
                });
            } else {
                success_count += 1;
            }
            continue;
        }

        let code = resolve_shop_sku_code(view);
        let mut matched = None;
        if !code.is_empty() {
            matched = match_code(pool, tenant_id, &code).await?;
        }

        let mut reason = if matched.is_none() {
            Some("未找到条码、辅助条码或编号对应货品".to_string())
        } else {
            None
        };

        if matched.is_none() {
            if let Some(merchant_code) = normalize_optional_string(view.merchant_code.clone()) {
                let candidates = build_merged_codes(&merchant_code, &code);
                for candidate in candidates {
                    matched = match_code(pool, tenant_id, &candidate).await?;
                    if matched.is_some() {
                        break;
                    }
                }
            }
        }

        if matched.is_none() {
            if let Some(name_match) = match_by_name_spec(pool, tenant_id, view).await? {
                matched = Some(name_match);
                reason = None;
            } else if view.product_title.trim().is_empty() {
                reason = Some("未找到条码、辅助条码或编号对应货品".to_string());
            } else {
                reason = Some("未找到名称规格对应货品".to_string());
            }
        }

        let Some(matched) = matched else {
            failure_count += 1;
            failures.push(ShopProductMatchFailure {
                sku_record_id: view.sku_record_id,
                platform_sku_id: view.platform_sku_id.clone(),
                merchant_sku_code: view.merchant_sku_code.clone(),
                reason: reason.unwrap_or_else(|| "自动匹配失败".to_string()),
            });
            continue;
        };

        match mapping_repo
            .create_mapping(ChannelSkuMappingCreate {
                tenant_id,
                shop_id: view.shop_id,
                platform: view.platform,
                platform_sku_id: view.platform_sku_id.clone(),
                platform_outer_sku_id: view.merchant_sku_code.clone(),
                sku_id: matched.sku_id,
                status: "ACTIVE".to_string(),
                conflict_reason: None,
                confidence: 0,
                match_source: "AUTO".to_string(),
            })
            .await
        {
            Ok(_) => success_count += 1,
            Err(e) => {
                failure_count += 1;
                failures.push(ShopProductMatchFailure {
                    sku_record_id: view.sku_record_id,
                    platform_sku_id: view.platform_sku_id.clone(),
                    merchant_sku_code: view.merchant_sku_code.clone(),
                    reason: format!("匹配写入失败: {e}"),
                });
            }
        }
    }

    Ok(AutoMatchSummary {
        total_count,
        success_count,
        failure_count,
        failures,
    })
}

async fn match_code(
    pool: &PgPool,
    tenant_id: TenantId,
    code: &str,
) -> anyhow::Result<Option<MatchedSku>> {
    if let Some(found) = find_sku_by_barcode(pool, tenant_id, code).await? {
        return Ok(Some(found));
    }
    if let Some(found) = find_sku_by_aux_barcode(pool, tenant_id, code).await? {
        return Ok(Some(found));
    }
    if let Some(found) = find_sku_by_sku_code(pool, tenant_id, code).await? {
        return Ok(Some(found));
    }
    Ok(None)
}

async fn find_sku_by_barcode(
    pool: &PgPool,
    tenant_id: TenantId,
    code: &str,
) -> anyhow::Result<Option<MatchedSku>> {
    let code = code.trim();
    if code.is_empty() {
        return Ok(None);
    }
    #[derive(sqlx::FromRow)]
    struct Row {
        sku_id: uuid::Uuid,
        sku_code: String,
        name: Option<String>,
        barcode: Option<String>,
        spec: Value,
    }
    let rows: Vec<Row> = sqlx::query_as(
        r#"
        select sku_id, sku_code, name, barcode, spec
        from skus
        where tenant_id = $1 and status <> 'DELETED' and barcode = $2
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(code)
    .fetch_all(pool)
    .await?;
    if rows.len() == 1 {
        let row = &rows[0];
        Ok(Some(MatchedSku {
            sku_id: row.sku_id,
            sku_code: row.sku_code.clone(),
            name: row.name.clone(),
            barcode: row.barcode.clone(),
            spec: row.spec.clone(),
        }))
    } else {
        Ok(None)
    }
}

