async fn match_by_name_spec(
    pool: &PgPool,
    tenant_id: TenantId,
    view: &ShopProductSkuView,
) -> anyhow::Result<Option<MatchedSku>> {
    let product_name = view.product_title.trim();
    if product_name.is_empty() {
        return Ok(None);
    }
    let target_spec = extract_spec_text(view).map(|value| value.to_lowercase());

    #[derive(sqlx::FromRow)]
    struct Row {
        sku_id: uuid::Uuid,
        sku_code: String,
        name: Option<String>,
        barcode: Option<String>,
        spec: Value,
    }

    let rows: Vec<Row> = sqlx::query_as(
        r#"
        select s.sku_id, s.sku_code, s.name, s.barcode, s.spec
        from skus s
        join products p
          on p.tenant_id = s.tenant_id
         and p.product_id = s.product_id
        where s.tenant_id = $1 and s.status <> 'DELETED' and lower(p.name) = $2
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(product_name.to_lowercase())
    .fetch_all(pool)
    .await?;

    if rows.is_empty() {
        return Ok(None);
    }

    let mut matched_rows = Vec::new();
    for row in rows {
        if let Some(target_spec) = target_spec.as_ref() {
            let candidate = extract_spec_text_from_spec(&row.spec)
                .map(|value| value.to_lowercase())
                .unwrap_or_default();
            if candidate == *target_spec {
                matched_rows.push(row);
            }
        } else {
            matched_rows.push(row);
        }
    }

    if matched_rows.len() == 1 {
        let row = matched_rows.remove(0);
        Ok(Some(MatchedSku {
            sku_id: row.sku_id,
            sku_code: row.sku_code,
            name: row.name,
            barcode: row.barcode,
            spec: row.spec,
        }))
    } else {
        Ok(None)
    }
}

fn extract_spec_text(view: &ShopProductSkuView) -> Option<String> {
    normalize_optional_string(view.spec_text.clone())
        .or_else(|| normalize_optional_string(view.sku_title.clone()))
}

fn resolve_shop_sku_code(view: &ShopProductSkuView) -> String {
    normalize_optional_string(view.merchant_sku_code.clone())
        .unwrap_or_else(|| view.platform_sku_id.clone())
}

fn extract_spec_text_from_spec(spec: &Value) -> Option<String> {
    match spec {
        Value::Object(map) => map
            .get("spec_text")
            .or_else(|| map.get("spec_value"))
            .or_else(|| map.get("spec"))
            .and_then(|value| value.as_str().map(|v| v.to_string())),
        Value::String(value) => Some(value.clone()),
        _ => None,
    }
}

fn build_merged_codes(product_code: &str, sku_code: &str) -> Vec<String> {
    let mut values = Vec::new();
    if !product_code.trim().is_empty() && !sku_code.trim().is_empty() {
        values.push(format!("{}{}", product_code.trim(), sku_code.trim()));
        values.push(format!("{}-{}", product_code.trim(), sku_code.trim()));
    }
    values
}

async fn load_shop_product_skus(
    pool: &PgPool,
    tenant_id: TenantId,
    sku_record_ids: Option<Vec<uuid::Uuid>>,
    filters: Option<ShopProductSkuFilterPayload>,
) -> Result<Vec<ShopProductSkuView>, Response> {
    let repo = ShopProductsRepo::new(pool);
    if let Some(ids) = sku_record_ids {
        return repo
            .list_sku_views_by_ids(tenant_id, &ids)
            .await
            .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response());
    }

    let Some(filters) = filters else {
        return Ok(Vec::new());
    };
    let platform = parse_platform_optional(filters.platform.as_deref())
        .map_err(|resp| resp.into_response())?;
    let shop_ids = parse_shop_ids_optional(filters.shop_ids.as_deref())
        .map_err(|resp| resp.into_response())?;
    let updated_from = parse_datetime_optional(filters.updated_from.as_deref(), "updated_from")
        .map_err(|resp| resp.into_response())?;
    let updated_to = parse_datetime_optional(filters.updated_to.as_deref(), "updated_to")
        .map_err(|resp| resp.into_response())?;
    let mut offset = 0;
    let limit = 200;
    let mut items = Vec::new();
    loop {
        let result = repo
            .list_sku_views(
                tenant_id,
                ShopProductSkuListFilters {
                    platform,
                    shop_ids: shop_ids.clone(),
                    product_type: normalize_optional_string(filters.product_type.clone()),
                    status: normalize_optional_string(filters.status.clone()),
                    keyword: normalize_optional_string(filters.keyword.clone()),
                    match_status: normalize_optional_string(filters.match_status.clone()),
                    mapping_status: normalize_optional_string(filters.mapping_status.clone()),
                    conflict_reason: normalize_optional_string(filters.conflict_reason.clone()),
                    match_source: normalize_optional_string(filters.match_source.clone()),
                    updated_from,
                    updated_to,
                    offset,
                    limit,
                },
            )
            .await
            .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response())?;
        items.extend(result.items);
        offset += limit;
        if offset >= result.total {
            break;
        }
    }
    Ok(items)
}

async fn resolve_unique_sku_code(
    pool: &PgPool,
    tenant_id: TenantId,
    base_code: &str,
) -> anyhow::Result<String> {
    let base = base_code.trim();
    let base_value = if base.is_empty() {
        format!("SHOP-{}", uuid::Uuid::new_v4())
    } else {
        base.to_string()
    };
    let mut candidate = base_value.clone();
    let mut index = 1;
    while sku_code_exists(pool, tenant_id, &candidate).await? {
        candidate = format!("{base_value}-{index}");
        index += 1;
    }
    Ok(candidate)
}

async fn sku_code_exists(
    pool: &PgPool,
    tenant_id: TenantId,
    sku_code: &str,
) -> anyhow::Result<bool> {
    let exists: Option<i32> = sqlx::query_scalar(
        r#"
        select 1
        from skus
        where tenant_id = $1 and sku_code = $2 and status <> 'DELETED'
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(sku_code)
    .fetch_optional(pool)
    .await?;
    Ok(exists.is_some())
}

fn build_shop_product_download_items_from_adapter(
    products: &[erp_adapter::PlatformProduct],
    default_product_type: Option<String>,
    default_status: Option<String>,
) -> Vec<ShopProductDownloadItem> {
    let fallback_type =
        normalize_optional_string(default_product_type).unwrap_or_else(|| "STANDARD".to_string());
    let fallback_status =
        normalize_optional_string(default_status).unwrap_or_else(|| "ACTIVE".to_string());
    products
        .iter()
        .map(|product| ShopProductDownloadItem {
            platform_product_id: product.platform_product_id.clone(),
            merchant_code: None,
            title: product.name.clone(),
            product_type: Some(fallback_type.clone()),
            status: Some(fallback_status.clone()),
            updated_at: None,
            raw_json: Some(product.raw.clone()),
            skus: product
                .skus
                .iter()
                .map(|sku| ShopProductDownloadSku {
                    platform_sku_id: sku.platform_sku_id.clone(),
                    merchant_sku_code: normalize_optional_string(sku.sku_code.clone()),
                    title: sku.name.clone(),
                    spec_text: extract_spec_text_from_platform_spec(sku.spec.as_ref()),
                    price_cent: None,
                    stock_qty: None,
                    status: Some(fallback_status.clone()),
                    barcode: sku.barcode.clone(),
                    image_url: sku.image_urls.first().cloned(),
                    updated_at: None,
                    raw_json: Some(sku.raw.clone()),
                })
                .collect(),
        })
        .collect()
}

fn extract_spec_text_from_platform_spec(spec: Option<&Value>) -> Option<String> {
    let spec = spec?;
    match spec {
        Value::Object(map) => map
            .get("spec_text")
            .or_else(|| map.get("spec"))
            .and_then(|value| value.as_str())
            .map(|value| value.to_string()),
        Value::String(value) => Some(value.clone()),
        _ => None,
    }
}

fn resolve_import_file_type(file_type: Option<&str>, file_name: Option<&str>) -> Option<String> {
    if let Some(raw) = file_type {
        let normalized = raw.trim().to_uppercase();
        if matches!(normalized.as_str(), "CSV" | "XLS" | "XLSX") {
            return Some(normalized);
        }
    }
    if let Some(name) = file_name {
        let lower = name.trim().to_lowercase();
        if lower.ends_with(".csv") {
            return Some("CSV".to_string());
        }
        if lower.ends_with(".xls") || lower.ends_with(".xlsx") {
            return Some("XLSX".to_string());
        }
    }
    Some("CSV".to_string())
}

fn decode_base64_payload(raw: &str) -> Result<Vec<u8>, (StatusCode, Json<ErrorResponse>)> {
    let trimmed = raw.trim();
    let payload = trimmed
        .split_once("base64,")
        .map(|(_, content)| content)
        .unwrap_or(trimmed);
    general_purpose::STANDARD
        .decode(payload)
        .map_err(|_| bad_request("invalid base64 payload"))
}

#[allow(clippy::result_large_err)]
fn parse_sku_import_rows(content: &[u8], file_type: &str) -> Result<Vec<SkuImportRow>, Response> {
    if file_type.eq_ignore_ascii_case("CSV") {
        return parse_sku_import_csv(content);
    }
    parse_sku_import_excel(content, file_type)
}

#[allow(clippy::result_large_err)]
fn parse_sku_import_csv(content: &[u8]) -> Result<Vec<SkuImportRow>, Response> {
    let mut reader = ReaderBuilder::new()
        .trim(csv::Trim::All)
        .from_reader(Cursor::new(content));
    let headers = reader
        .headers()
        .map_err(|_| bad_request("invalid csv headers").into_response())?
        .iter()
        .map(normalize_import_header)
        .collect::<Vec<_>>();
    let indexes = build_sku_import_header_index(&headers)?;

    let mut rows = Vec::new();
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|_| bad_request("invalid csv row").into_response())?;
        let row = parse_sku_import_row(
            index as i64 + 2,
            |idx| {
                idx.and_then(|i| record.get(i))
                    .map(|value| value.to_string())
            },
            &indexes,
        );
        rows.push(row);
    }
    Ok(rows)
}

#[allow(clippy::result_large_err)]
fn parse_sku_import_excel(content: &[u8], file_type: &str) -> Result<Vec<SkuImportRow>, Response> {
    let temp_path = write_temp_import_file(content, file_type)?;
    let mut workbook = open_workbook_auto(&temp_path)
        .map_err(|_| bad_request("invalid excel file").into_response())?;
    let sheet_name = workbook
        .sheet_names()
        .first()
        .cloned()
        .ok_or_else(|| bad_request("missing sheet").into_response())?;
    let range = workbook
        .worksheet_range(&sheet_name)
        .map_err(|_| bad_request("invalid sheet").into_response())?;

    let mut rows_iter = range.rows();
    let header_row = rows_iter
        .next()
        .ok_or_else(|| bad_request("empty sheet").into_response())?;
    let headers = header_row
        .iter()
        .map(|cell| normalize_import_header(&cell.to_string()))
        .collect::<Vec<_>>();
    let indexes = build_sku_import_header_index(&headers)?;

    let mut rows = Vec::new();
    for (index, row) in rows_iter.enumerate() {
        let values = row.iter().map(cell_string).collect::<Vec<_>>();
        let parsed = parse_sku_import_row(
            index as i64 + 2,
            |idx| idx.and_then(|i| values.get(i)).cloned(),
            &indexes,
        );
        rows.push(parsed);
    }

    let _ = fs::remove_file(&temp_path);
    Ok(rows)
}

#[allow(clippy::result_large_err)]
fn write_temp_import_file(content: &[u8], file_type: &str) -> Result<PathBuf, Response> {
    let mut path = std::env::temp_dir();
    let ext = if file_type.eq_ignore_ascii_case("CSV") {
        "csv"
    } else if file_type.eq_ignore_ascii_case("XLS") {
        "xls"
    } else {
        "xlsx"
    };
    path.push(format!("sku-import-{}.{}", uuid::Uuid::new_v4(), ext));
    fs::write(&path, content).map_err(|_| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            "failed to write temp file",
        )
            .into_response()
    })?;
    Ok(path)
}

fn parse_sku_import_row<F: Fn(Option<usize>) -> Option<String>>(
    row_number: i64,
    get: F,
    indexes: &SkuImportHeaderIndex,
) -> SkuImportRow {
    let product_id = get(indexes.product_id).and_then(|value| optional_string(&value));
    let product_name = get(indexes.product_name).and_then(|value| optional_string(&value));
    let sku_code = get(indexes.sku_code).unwrap_or_default();
    let sku_code = sku_code.trim().to_string();
    let barcode = get(indexes.barcode).and_then(|value| optional_string(&value));
    let aux_barcode = get(indexes.aux_barcode).and_then(|value| optional_string(&value));
    let name = get(indexes.name).and_then(|value| optional_string(&value));
    let spec = get(indexes.spec).and_then(|value| optional_string(&value));
    let unit = get(indexes.unit).and_then(|value| optional_string(&value));
    let category_id = get(indexes.category_id).and_then(|value| optional_string(&value));
    let category_name = get(indexes.category_name).and_then(|value| optional_string(&value));
    let sku_kind = get(indexes.sku_kind).and_then(|value| optional_string(&value));
    let tags_raw = get(indexes.tags).unwrap_or_default();
    let tags = normalize_string_list(split_import_list(tags_raw.as_str()));
    let image_urls_raw = get(indexes.image_urls).unwrap_or_default();
    let image_urls = normalize_string_list(split_import_list(image_urls_raw.as_str()));
    let cost_cent = get(indexes.cost_cent).and_then(|value| optional_string(&value));
    let supplier_ids_raw = get(indexes.supplier_ids).unwrap_or_default();
    let supplier_ids = normalize_string_list(split_import_list(supplier_ids_raw.as_str()));
    let weight_gram = get(indexes.weight_gram).and_then(|value| optional_string(&value));
    let length_mm = get(indexes.length_mm).and_then(|value| optional_string(&value));
    let width_mm = get(indexes.width_mm).and_then(|value| optional_string(&value));
    let height_mm = get(indexes.height_mm).and_then(|value| optional_string(&value));
    let volume_cm3 = get(indexes.volume_cm3).and_then(|value| optional_string(&value));

    SkuImportRow {
        row: row_number,
        product_id,
        product_name,
        sku_code,
        barcode,
        aux_barcode,
        name,
        spec,
        unit,
        category_id,
        category_name,
        sku_kind,
        tags,
        image_urls,
        cost_cent,
        supplier_ids,
        weight_gram,
        length_mm,
        width_mm,
        height_mm,
        volume_cm3,
    }
}

fn normalize_import_header(value: &str) -> String {
    value
        .trim()
        .to_lowercase()
        .replace([' ', '-', '/', '.', '(', ')', '（', '）'], "_")
        .replace("__", "_")
        .trim_matches('_')
        .to_string()
}

#[allow(clippy::result_large_err)]
fn build_sku_import_header_index(headers: &[String]) -> Result<SkuImportHeaderIndex, Response> {
    let mut index = SkuImportHeaderIndex::default();
    for (idx, header) in headers.iter().enumerate() {
        match header.as_str() {
            "product_id" | "productid" | "货品编号" | "鍟嗗搧编号" | "浜у搧编号" => {
                index.product_id = Some(idx)
            }
            "product_name" | "product" | "productname" | "货品鍚嶇О" | "鍟嗗搧鍚嶇О"
            | "浜у搧鍚嶇О" => index.product_name = Some(idx),
            "sku_code" | "sku" | "skucode" | "规格编号" | "规格编码" | "sku编号"
            | "sku缂栫爜" => index.sku_code = Some(idx),
            "barcode" | "bar_code" | "鏉＄爜" => index.barcode = Some(idx),
            "aux_barcode" | "assistant_barcode" | "辅助条码" | "辅助码" => {
                index.aux_barcode = Some(idx)
            }
            "name" | "sku_name" | "sku鍚嶇О" | "瑙勬牸鍚嶇О" => index.name = Some(idx),
            "spec" | "spec_info" | "规格信息" | "规格" => index.spec = Some(idx),
            "unit" | "鍗曚綅" => index.unit = Some(idx),
            "category_id" | "categoryid" | "分类编号" | "鍒嗙被id" | "分类编码" => {
                index.category_id = Some(idx)
            }
            "category_name" | "category" | "鍒嗙被鍚嶇О" | "鍒嗙被" => {
                index.category_name = Some(idx)
            }
            "sku_kind" | "kind" | "type" | "瑙勬牸绫诲瀷" | "sku绫诲瀷" => {
                index.sku_kind = Some(idx)
            }
            "tags" | "tag" | "标签" => index.tags = Some(idx),
            "image_urls" | "images" | "image_url" | "鍥剧墖" | "鍥剧墖閾炬帴" => {
                index.image_urls = Some(idx)
            }
            "cost_cent" | "cost" | "鎴愭湰" => index.cost_cent = Some(idx),
            "supplier_ids" | "suppliers" | "supplier_id" | "供应商" | "供应商id" => {
                index.supplier_ids = Some(idx)
            }
            "weight_gram" | "weight" | "weight_g" | "閲嶉噺" | "閲嶉噺g" | "閲嶉噺_g" => {
                index.weight_gram = Some(idx)
            }
            "length_mm" | "length" | "闀垮害" | "闀垮害_mm" => index.length_mm = Some(idx),
            "width_mm" | "width" | "瀹藉害" | "瀹藉害_mm" => index.width_mm = Some(idx),
            "height_mm" | "height" | "楂樺害" | "楂樺害_mm" => index.height_mm = Some(idx),
            "volume_cm3" | "volume" | "浣撶Н" | "浣撶Н_cm3" => index.volume_cm3 = Some(idx),
            _ => {}
        }
    }
    if index.sku_code.is_none() {
        return Err(bad_request("missing sku_code column").into_response());
    }
    if index.product_id.is_none() && index.product_name.is_none() {
        return Err(bad_request("missing product_id or product_name column").into_response());
    }
    if index.unit.is_none() {
        return Err(bad_request("missing unit column").into_response());
    }
    if index.category_id.is_none() && index.category_name.is_none() {
        return Err(bad_request("missing category column").into_response());
    }
    Ok(index)
}

fn split_import_list(raw: &str) -> Vec<String> {
    raw.split([',', ';', '|'])
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
        .map(|value| value.to_string())
        .collect()
}

fn optional_string(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed.to_string())
    }
}

fn cell_string(cell: &Data) -> String {
    match cell {
        Data::String(value) => value.trim().to_string(),
        Data::Float(value) => {
            if value.fract() == 0.0 {
                format!("{:.0}", value)
            } else {
                value.to_string()
            }
        }
        Data::Int(value) => value.to_string(),
        Data::Bool(value) => value.to_string(),
        _ => cell.to_string(),
    }
}

fn push_import_issue(
    errors: &mut Vec<SkuImportIssue>,
    invalid_rows: &mut HashSet<i64>,
    row: i64,
    field: Option<&str>,
    message: &str,
) {
    errors.push(SkuImportIssue {
        row,
        field: field.map(|value| value.to_string()),
        message: message.to_string(),
    });
    invalid_rows.insert(row);
}

fn parse_optional_i64_field(
    raw: Option<&str>,
    field: &str,
    row: i64,
    errors: &mut Vec<SkuImportIssue>,
    invalid_rows: &mut HashSet<i64>,
) -> Option<i64> {
    let value = raw.map(str::trim).filter(|v| !v.is_empty())?;
    match value.parse::<i64>() {
        Ok(v) => Some(v),
        Err(_) => {
            push_import_issue(errors, invalid_rows, row, Some(field), "invalid number");
            None
        }
    }
}

fn parse_optional_i32_field(
    raw: Option<&str>,
    field: &str,
    row: i64,
    errors: &mut Vec<SkuImportIssue>,
    invalid_rows: &mut HashSet<i64>,
) -> Option<i32> {
    let value = raw.map(str::trim).filter(|v| !v.is_empty())?;
    match value.parse::<i32>() {
        Ok(v) => Some(v),
        Err(_) => {
            push_import_issue(errors, invalid_rows, row, Some(field), "invalid number");
            None
        }
    }
}

async fn fetch_existing_sku_codes(
    pool: &sqlx::PgPool,
    tenant_id: TenantId,
    sku_codes: &[String],
) -> Result<HashSet<String>, (StatusCode, Json<ErrorResponse>)> {
    if sku_codes.is_empty() {
        return Ok(HashSet::new());
    }
    let rows: Vec<String> = sqlx::query_scalar(
        r#"
        select sku_code
        from skus
        where tenant_id = $1
          and status <> 'DELETED'
          and sku_code = any($2)
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(sku_codes)
    .fetch_all(pool)
    .await
    .map_err(|e| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(ErrorResponse {
                code: "internal_error".to_string(),
                message: format!("failed to load sku codes: {e}"),
                details: None,
                request_id: None,
            }),
        )
    })?;
    Ok(rows.into_iter().collect())
}

