async fn fetch_product_categories_by_id(
    pool: &sqlx::PgPool,
    tenant_id: TenantId,
    product_ids: &[uuid::Uuid],
) -> Result<HashMap<uuid::Uuid, Option<String>>, (StatusCode, Json<ErrorResponse>)> {
    if product_ids.is_empty() {
        return Ok(HashMap::new());
    }
    #[derive(sqlx::FromRow)]
    struct Row {
        product_id: uuid::Uuid,
        category: Option<String>,
    }
    let rows: Vec<Row> = sqlx::query_as(
        r#"
        select product_id, category
        from products
        where tenant_id = $1
          and status <> 'DELETED'
          and product_id = any($2)
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(product_ids)
    .fetch_all(pool)
    .await
    .map_err(|e| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(ErrorResponse {
                code: "internal_error".to_string(),
                message: format!("failed to load product categories: {e}"),
                details: None,
                request_id: None,
            }),
        )
    })?;

    let mut map = HashMap::new();
    for row in rows {
        map.insert(row.product_id, row.category);
    }
    Ok(map)
}

