fn write_sku_import_file(
    content: &[u8],
    tenant_id: TenantId,
    file_type: &str,
) -> Result<PathBuf, (StatusCode, Json<ErrorResponse>)> {
    let mut path = sku_import_base_dir();
    path.push(tenant_id.to_string());
    fs::create_dir_all(&path).map_err(|_| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(ErrorResponse {
                code: "internal_error".to_string(),
                message: "failed to create import directory".to_string(),
                details: None,
                request_id: None,
            }),
        )
    })?;
    let ext = if file_type.eq_ignore_ascii_case("CSV") {
        "csv"
    } else if file_type.eq_ignore_ascii_case("XLS") {
        "xls"
    } else {
        "xlsx"
    };
    path.push(format!("sku-import-{}.{}", uuid::Uuid::new_v4(), ext));
    fs::write(&path, content).map_err(|_| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(ErrorResponse {
                code: "internal_error".to_string(),
                message: "failed to write import file".to_string(),
                details: None,
                request_id: None,
            }),
        )
    })?;
    Ok(path)
}

fn sku_import_base_dir() -> PathBuf {
    std::env::var("SKU_IMPORT_BASE_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from("imports/sku"))
}

fn sku_import_file_path(tenant_id: TenantId, file_id: uuid::Uuid, file_type: &str) -> PathBuf {
    let ext = if file_type.eq_ignore_ascii_case("CSV") {
        "csv"
    } else if file_type.eq_ignore_ascii_case("XLS") {
        "xls"
    } else {
        "xlsx"
    };
    let mut path = sku_import_base_dir();
    path.push(tenant_id.to_string());
    path.push(format!("sku-import-{file_id}.{ext}"));
    path
}

fn sku_import_template_path() -> PathBuf {
    std::env::var("SKU_IMPORT_TEMPLATE_PATH")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from("assets/sku_import_template.xlsx"))
}

fn sku_import_failure_file_path(tenant_id: TenantId, job_id: uuid::Uuid) -> PathBuf {
    let mut base = sku_import_failure_base_dir();
    base.push(tenant_id.to_string());
    base.push(format!("{job_id}.csv"));
    base
}

fn sku_import_failure_base_dir() -> PathBuf {
    std::env::var("SKU_IMPORT_FAILURE_BASE_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from("imports/sku_failures"))
}

async fn bind_serials_for_shipment(
    state: &AppState,
    tenant_id: TenantId,
    shipment_id: uuid::Uuid,
    order_id: OrderId,
    serials: Vec<ShipmentSerialEntry>,
) -> Result<Vec<SkuSerial>, axum::response::Response> {
    let mut bound = Vec::new();
    for entry in serials {
        if entry.serial_nos.is_empty() {
            return Err(bad_request("serial_nos required").into_response());
        }
        let sku_id = match entry.sku_id.as_deref() {
            Some(raw) => match uuid::Uuid::parse_str(raw) {
                Ok(v) => v,
                Err(_) => return Err(bad_request("bad sku_id").into_response()),
            },
            None => return Err(bad_request("sku_id required").into_response()),
        };

        let base_order_item_id = order_item_uuid(uuid::Uuid::from(order_id), &entry.line_id);
        let order_item_id = match resolve_serial_order_item_id(
            state.db.pool(),
            tenant_id,
            order_id,
            base_order_item_id,
            sku_id,
        )
        .await
        {
            Ok(v) => v,
            Err(e) => {
                return Err((StatusCode::INTERNAL_SERVER_ERROR, format!("{e}")).into_response())
            }
        };

        let serials = match state
            .sku_serials_repo
            .bind_serials_to_shipment(RepoShipmentSerialBindInput {
                tenant_id,
                shipment_id,
                order_id: uuid::Uuid::from(order_id),
                order_item_id,
                sku_id,
                serial_nos: entry.serial_nos,
            })
            .await
        {
            Ok(v) => v,
            Err(e) => return Err(serial_bind_error_response(e)),
        };
        bound.extend(serials);
    }
    Ok(bound)
}

async fn resolve_serial_order_item_id(
    pool: &sqlx::PgPool,
    tenant_id: TenantId,
    order_id: OrderId,
    base_order_item_id: uuid::Uuid,
    sku_id: uuid::Uuid,
) -> anyhow::Result<uuid::Uuid> {
    let exists: Option<i32> = sqlx::query_scalar(
        r#"
        select 1
        from order_item_components
        where tenant_id = $1
          and order_id = $2
          and order_item_id = $3
          and component_sku_id = $4
        limit 1
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(uuid::Uuid::from(order_id))
    .bind(base_order_item_id)
    .bind(sku_id)
    .fetch_optional(pool)
    .await?;

    if exists.is_some() {
        Ok(component_order_item_id(base_order_item_id, sku_id))
    } else {
        Ok(base_order_item_id)
    }
}

fn order_item_uuid(order_id: uuid::Uuid, line_id: &str) -> uuid::Uuid {
    uuid::Uuid::parse_str(line_id)
        .unwrap_or_else(|_| uuid::Uuid::new_v5(&order_id, line_id.as_bytes()))
}

fn component_order_item_id(order_item_id: uuid::Uuid, component_sku_id: uuid::Uuid) -> uuid::Uuid {
    uuid::Uuid::new_v5(&order_item_id, component_sku_id.as_bytes())
}

fn derive_delivery_status(outbound_status: &str, ship_status: &str) -> String {
    if ship_status == "SHIPPED" || outbound_status == "SHIPPED" {
        "SHIPPED".to_string()
    } else {
        "NOT_SHIPPED".to_string()
    }
}

fn format_sales_order_status(label: &str, value: Option<&str>) -> Option<String> {
    value.map(|value| format!("{label}:{value}"))
}

fn append_status_flags(flags: &[String], additions: &[&str]) -> Vec<String> {
    let mut next = flags.to_vec();
    for addition in additions {
        if !next.iter().any(|flag| flag == addition) {
            next.push(addition.to_string());
        }
    }
    next
}

#[allow(clippy::too_many_arguments)]
async fn record_sales_order_state_logs(
    state: &AppState,
    req_ctx: &RequestContext,
    tenant_id: TenantId,
    sales_order_id: uuid::Uuid,
    action_code: &str,
    from_status: Option<String>,
    to_status: Option<String>,
    operator_id: Option<UserId>,
    reason: Option<String>,
    request_payload: serde_json::Value,
    response_payload: serde_json::Value,
) {
    let Some(to_status) = to_status else {
        return;
    };

    let request_payload_clone = request_payload.clone();
    let response_payload_clone = response_payload.clone();
    let request_json = serde_json::json!({
        "trace_id": req_ctx.trace_id,
        "request_id": req_ctx.request_id,
        "payload": request_payload,
    });
    let response_json = serde_json::json!({
        "payload": response_payload,
    });
    let action_repo = OrderActionLogsRepo::new(state.db.pool());
    let _ = action_repo
        .insert(OrderActionLogCreate {
            tenant_id,
            order_id: OrderId::from(sales_order_id),
            action_code: action_code.to_string(),
            idempotency_key: req_ctx.request_id.clone(),
            status: Some("SUCCESS".to_string()),
            operator_id,
            request_json: Some(request_json),
            response_json: Some(response_json),
            error_message: None,
        })
        .await;

    let history_repo = OrderStatusHistoryRepo::new(state.db.pool());
    let history_reason = reason.clone();
    let payload = serde_json::json!({
        "trace_id": req_ctx.trace_id,
        "request_id": req_ctx.request_id,
        "reason": reason,
        "request": request_payload_clone,
        "response": response_payload_clone,
    });
    let _ = history_repo
        .insert(OrderStatusHistoryCreate {
            tenant_id,
            order_id: OrderId::from(sales_order_id),
            from_status,
            to_status,
            action_code: Some(action_code.to_string()),
            operator_id,
            reason: history_reason,
            payload: Some(payload),
        })
        .await;
}

#[allow(clippy::too_many_arguments)]
async fn record_audit_log(
    state: &AppState,
    ctx: &AuthContext,
    req_ctx: &RequestContext,
    action: &str,
    entity_type: &str,
    entity_id: Option<String>,
    before: Option<Value>,
    after: Option<Value>,
) {
    let repo = AuditLogsRepo::new(state.db.pool());
    let _ = repo
        .insert(AuditLogCreate {
            tenant_id: ctx.tenant_id,
            user_id: Some(ctx.user_id),
            action: action.to_string(),
            entity_type: entity_type.to_string(),
            entity_id,
            before_json: before,
            after_json: after,
            ip: req_ctx.ip.clone(),
            ua: req_ctx.user_agent.clone(),
        })
        .await;
}

fn ensure_permission(
    ctx: &AuthContext,
    perm: &str,
) -> Result<(), (StatusCode, Json<ErrorResponse>)> {
    if ctx.is_admin {
        return Ok(());
    }
    let required = normalize_permission_code(perm);
    if ctx.perms.iter().any(|p| p == &required) {
        Ok(())
    } else {
        Err(forbidden("missing permission"))
    }
}

fn ensure_permission_any(
    ctx: &AuthContext,
    perms: &[&str],
) -> Result<(), (StatusCode, Json<ErrorResponse>)> {
    if ctx.is_admin {
        return Ok(());
    }
    if perms.iter().any(|perm| {
        let required = normalize_permission_code(perm);
        ctx.perms.iter().any(|p| p == &required)
    }) {
        Ok(())
    } else {
        Err(forbidden("missing permission"))
    }
}

fn ensure_admin(ctx: &AuthContext) -> Result<(), (StatusCode, Json<ErrorResponse>)> {
    if ctx.is_admin {
        Ok(())
    } else {
        Err(forbidden("admin access required"))
    }
}

fn ensure_tenant_access(
    ctx: &AuthContext,
    tenant_id: TenantId,
) -> Result<(), (StatusCode, Json<ErrorResponse>)> {
    if ctx.tenant_id == tenant_id || ctx.is_admin {
        Ok(())
    } else {
        Err(forbidden("tenant mismatch"))
    }
}

fn ensure_shop_access(
    ctx: &AuthContext,
    shop_id: ShopId,
) -> Result<(), (StatusCode, Json<ErrorResponse>)> {
    if ctx.is_admin || ctx.shop_ids.is_empty() || ctx.shop_ids.contains(&shop_id) {
        Ok(())
    } else {
        Err(forbidden("shop access denied"))
    }
}

fn ensure_warehouse_access(
    ctx: &AuthContext,
    warehouse_id: uuid::Uuid,
) -> Result<(), (StatusCode, Json<ErrorResponse>)> {
    if ctx.is_admin || ctx.warehouse_ids.is_empty() || ctx.warehouse_ids.contains(&warehouse_id) {
        Ok(())
    } else {
        Err(forbidden("warehouse access denied"))
    }
}

fn shop_scope_filter(ctx: &AuthContext) -> Option<Vec<ShopId>> {
    if ctx.is_admin || ctx.shop_ids.is_empty() {
        None
    } else {
        Some(ctx.shop_ids.clone())
    }
}

fn warehouse_scope_filter(ctx: &AuthContext) -> Option<Vec<uuid::Uuid>> {
    if ctx.is_admin || ctx.warehouse_ids.is_empty() {
        None
    } else {
        Some(ctx.warehouse_ids.clone())
    }
}

fn ensure_shop_scope_subset(
    ctx: &AuthContext,
    requested: &[ShopId],
) -> Result<(), (StatusCode, Json<ErrorResponse>)> {
    if ctx.is_admin || ctx.shop_ids.is_empty() {
        return Ok(());
    }
    for shop_id in requested {
        if !ctx.shop_ids.contains(shop_id) {
            return Err(forbidden("shop access denied"));
        }
    }
    Ok(())
}

fn ensure_uuid_scope_subset(
    ctx: &AuthContext,
    requested: &[uuid::Uuid],
    allowed: &[uuid::Uuid],
    label: &str,
) -> Result<(), (StatusCode, Json<ErrorResponse>)> {
    if ctx.is_admin || allowed.is_empty() {
        return Ok(());
    }
    for id in requested {
        if !allowed.contains(id) {
            return Err(forbidden(&format!("{label} access denied")));
        }
    }
    Ok(())
}

async fn pdd_only_mode_enabled(
    state: &AppState,
    tenant_id: TenantId,
) -> Result<bool, (StatusCode, Json<ErrorResponse>)> {
    if let Some(enabled) = feature_flags::pdd_only_mode_env() {
        return Ok(enabled);
    }

    let tenants_repo = TenantsRepo::new(state.db.pool());
    match tenants_repo.is_pdd_only_mode(tenant_id).await {
        Ok(v) => Ok(v),
        Err(e) => {
            warn!(tenant_id = %tenant_id, error = %e, "failed to load pdd-only mode");
            Ok(false)
        }
    }
}

async fn feature_flag_enabled(
    state: &AppState,
    tenant_id: TenantId,
    shop_id: Option<ShopId>,
    key: FeatureFlagKey,
) -> Result<bool, (StatusCode, Json<ErrorResponse>)> {
    let repo = FeatureFlagsRepo::new(state.db.pool());
    let flag = FeatureFlag::from_common_key(key);
    match repo.is_enabled(tenant_id, shop_id, flag).await {
        Ok(v) => Ok(v),
        Err(e) => {
            let shop_id_str = shop_id.map(|id| id.to_string());
            warn!(
                tenant_id = %tenant_id,
                shop_id = shop_id_str.as_deref(),
                feature = %key,
                error = %e,
                "failed to load feature flag"
            );
            Err(error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "internal_error",
                "failed to load feature flag",
            ))
        }
    }
}

fn is_write_method(method: &Method) -> bool {
    matches!(
        *method,
        Method::POST | Method::PUT | Method::PATCH | Method::DELETE
    )
}

fn tenant_id_from_path(path: &str) -> Option<TenantId> {
    let mut segments = path.trim_matches('/').split('/');
    match (segments.next(), segments.next(), segments.next()) {
        (Some("v1"), Some("tenants"), Some(raw)) => TenantId::from_str(raw).ok(),
        _ => None,
    }
}

