fn parse_shop_status(
    raw: Option<String>,
) -> Result<Option<String>, (StatusCode, Json<ErrorResponse>)> {
    let Some(status) = raw else {
        return Ok(None);
    };
    let normalized = status.trim().to_uppercase();
    if normalized.is_empty() {
        return Ok(None);
    }
    match normalized.as_str() {
        "AUTHORIZED" | "EXPIRED" | "DISABLED" => Ok(Some(normalized)),
        _ => Err(bad_request("invalid shop status")),
    }
}

fn parse_channel_status(
    raw: Option<String>,
) -> Result<Option<String>, (StatusCode, Json<ErrorResponse>)> {
    let Some(status) = raw else {
        return Ok(None);
    };
    let normalized = status.trim().to_uppercase();
    if normalized.is_empty() {
        return Ok(None);
    }
    match normalized.as_str() {
        "ACTIVE" | "DISABLED" => Ok(Some(normalized)),
        _ => Err(bad_request("invalid channel status")),
    }
}

fn bad_request(message: &str) -> (StatusCode, Json<ErrorResponse>) {
    error_response(StatusCode::BAD_REQUEST, "bad_request", message)
}

fn forbidden(message: &str) -> (StatusCode, Json<ErrorResponse>) {
    error_response(StatusCode::FORBIDDEN, "forbidden", message)
}

fn conflict(message: &str) -> (StatusCode, Json<ErrorResponse>) {
    error_response(StatusCode::CONFLICT, "conflict", message)
}

fn not_found(message: &str) -> (StatusCode, Json<ErrorResponse>) {
    error_response(StatusCode::NOT_FOUND, "not_found", message)
}

fn error_response(
    status: StatusCode,
    code: &str,
    message: &str,
) -> (StatusCode, Json<ErrorResponse>) {
    (
        status,
        Json(ErrorResponse {
            code: code.to_string(),
            message: message.to_string(),
            details: None,
            request_id: None,
        }),
    )
}

