async fn ensure_default_stock_count_strategies(
    state: &AppState,
    tenant_id: TenantId,
) -> anyhow::Result<()> {
    let repo = StockCountStrategiesRepo::new(state.db.pool());
    let existing = repo
        .list_strategies(
            tenant_id,
            StockCountStrategyListFilters {
                enabled: None,
                offset: 0,
                limit: 1,
            },
        )
        .await?;
    if existing.total > 0 {
        return Ok(());
    }

    let defaults = vec![
        (
            "每周全仓盘点",
            "WEEKLY_FULL",
            serde_json::json!({ "weekday": 1 }),
        ),
        (
            "每日动销SKU盘点",
            "DAILY_ACTIVE_SKU",
            serde_json::json!({ "recent_days": 7 }),
        ),
        (
            "缺货/负库存盘点",
            "NEGATIVE_STOCK",
            serde_json::json!({ "include_zero": true }),
        ),
    ];

    for (name, strategy_type, config_json) in defaults {
        let _ = repo
            .create_strategy(StockCountStrategyCreate {
                tenant_id,
                name: name.to_string(),
                enabled: true,
                strategy_type: strategy_type.to_string(),
                config_json,
            })
            .await;
    }

    Ok(())
}

