async fn save_sales_shop_config(
    state: &AppState,
    tenant_id: TenantId,
    shop: Shop,
    config: SalesShopConfig,
    ctx: &AuthContext,
    req_ctx: &RequestContext,
    audit_action: &str,
) -> Result<ShopSalesConfigView, Response> {
    let settings_repo = SettingsRepo::new(state.db.pool());
    for (key, value_json) in config.to_settings() {
        let result = settings_repo
            .upsert_setting(SettingUpsert {
                tenant_id,
                scope_type: "SHOP".to_string(),
                scope_id: Some(uuid::Uuid::from(shop.shop_id)),
                key,
                value_json,
                expected_version: None,
            })
            .await;
        if let Err(err) = result {
            if err.to_string().contains("version conflict") {
                return Err(conflict("settings version conflict").into_response());
            }
            return Err((StatusCode::INTERNAL_SERVER_ERROR, format!("{err}")).into_response());
        }
    }

    let sync_repo = SyncJobsRepo::new(state.db.pool());
    let _ = sync_repo
        .update_job_status(
            tenant_id,
            shop.shop_id,
            "order_sync",
            if config.auto_download_orders {
                "PENDING"
            } else {
                "DISABLED"
            },
            if config.auto_download_orders {
                None
            } else {
                Some("disabled by sales config".to_string())
            },
        )
        .await;
    let _ = sync_repo
        .update_job_status(
            tenant_id,
            shop.shop_id,
            "refund_sync",
            if config.enable_after_sales_download {
                "PENDING"
            } else {
                "DISABLED"
            },
            if config.enable_after_sales_download {
                None
            } else {
                Some("disabled by sales config".to_string())
            },
        )
        .await;
    let _ = sync_repo
        .update_job_status(
            tenant_id,
            shop.shop_id,
            "shipping_sync",
            if config.enable_logistics_upload {
                "PENDING"
            } else {
                "DISABLED"
            },
            if config.enable_logistics_upload {
                None
            } else {
                Some("disabled by sales config".to_string())
            },
        )
        .await;

    record_audit_log(
        state,
        ctx,
        req_ctx,
        audit_action,
        "shop",
        Some(shop.shop_id.to_string()),
        None,
        Some(serde_json::json!({
            "shop_id": shop.shop_id,
            "config": &config,
        })),
    )
    .await;

    Ok(sales_shop_config_view(shop, config))
}

fn shop_token_status(token: &PlatformToken) -> ShopTokenStatus {
    let now = Utc::now();
    let (expires_in_minutes, is_expired, is_expiring_soon) = match token.expires_at {
        Some(expires_at) => {
            let delta = expires_at.signed_duration_since(now).num_minutes();
            let expired = expires_at <= now;
            let expiring_soon = expires_at <= now + Duration::minutes(30);
            (Some(delta), expired, expiring_soon)
        }
        None => (None, false, false),
    };

    ShopTokenStatus {
        token_status: token.token_status.clone(),
        has_access_token: token.access_token.is_some(),
        has_refresh_token: token.refresh_token.is_some(),
        expires_at: token.expires_at,
        expires_in_minutes,
        is_expired,
        is_expiring_soon,
        scopes: token.scopes.clone(),
        last_refreshed_at: token.last_refreshed_at,
        refresh_fail_count: token.refresh_fail_count,
        last_error: token.last_error.clone(),
        updated_at: token.updated_at,
    }
}

async fn load_sales_config_for_shop(
    pool: &sqlx::PgPool,
    tenant_id: TenantId,
    shop_id: ShopId,
) -> anyhow::Result<SalesShopConfig> {
    let mut configs = load_sales_configs_for_shops(pool, tenant_id, &[shop_id]).await?;
    Ok(configs.remove(&shop_id).unwrap_or_default())
}

async fn load_sales_configs_for_shops(
    pool: &sqlx::PgPool,
    tenant_id: TenantId,
    shop_ids: &[ShopId],
) -> anyhow::Result<HashMap<ShopId, SalesShopConfig>> {
    let mut configs: HashMap<ShopId, SalesShopConfig> = HashMap::new();
    for shop_id in shop_ids {
        configs.insert(*shop_id, SalesShopConfig::default());
    }
    if shop_ids.is_empty() {
        return Ok(configs);
    }

    #[derive(sqlx::FromRow)]
    struct Row {
        scope_id: uuid::Uuid,
        key: String,
        value_json: Value,
    }

    let rows: Vec<Row> = sqlx::query_as(
        r#"
        select scope_id, key, value_json
        from settings
        where tenant_id = $1
          and scope_type = 'SHOP'
          and scope_id = any($2)
          and key = any($3)
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(
        shop_ids
            .iter()
            .map(|id| uuid::Uuid::from(*id))
            .collect::<Vec<_>>(),
    )
    .bind(
        sales_settings::SALES_CONFIG_KEYS
            .iter()
            .map(|key| key.to_string())
            .collect::<Vec<_>>(),
    )
    .fetch_all(pool)
    .await?;

    for row in rows {
        let shop_id = ShopId(row.scope_id);
        let entry = configs.entry(shop_id).or_default();
        entry.apply_setting(&row.key, &row.value_json);
    }

    Ok(configs)
}

async fn load_shop_credentials_for_shops(
    pool: &sqlx::PgPool,
    tenant_id: TenantId,
    shop_ids: &[ShopId],
) -> anyhow::Result<HashMap<ShopId, Value>> {
    let mut credentials = HashMap::new();
    if shop_ids.is_empty() {
        return Ok(credentials);
    }

    #[derive(sqlx::FromRow)]
    struct Row {
        shop_id: uuid::Uuid,
        credentials: Value,
    }

    let rows: Vec<Row> = sqlx::query_as(
        r#"
        select shop_id, credentials
        from shops
        where tenant_id = $1
          and shop_id = any($2)
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(
        shop_ids
            .iter()
            .map(|id| uuid::Uuid::from(*id))
            .collect::<Vec<_>>(),
    )
    .fetch_all(pool)
    .await?;

    for row in rows {
        credentials.insert(ShopId(row.shop_id), row.credentials);
    }

    Ok(credentials)
}

async fn load_shop_webhook_health_for_shops(
    pool: &sqlx::PgPool,
    tenant_id: TenantId,
    shop_ids: &[ShopId],
) -> anyhow::Result<HashMap<ShopId, ShopWebhookHealthSummary>> {
    let mut health_by_shop = HashMap::new();
    if shop_ids.is_empty() {
        return Ok(health_by_shop);
    }

    #[derive(sqlx::FromRow)]
    struct Row {
        shop_id: uuid::Uuid,
        last_webhook_received_at: Option<DateTime<Utc>>,
        last_webhook_processed_at: Option<DateTime<Utc>>,
        webhook_failed_count: i64,
        webhook_verify_failed_count: i64,
        webhook_pending_count: i64,
        webhook_retrying_count: i64,
        webhook_dlq_count: i64,
        webhook_next_retry_at: Option<DateTime<Utc>>,
        oldest_pending_at: Option<DateTime<Utc>>,
    }

    let rows: Vec<Row> = sqlx::query_as(
        r#"
        with requested_shops as (
          select unnest($2::uuid[]) as shop_id
        ),
        inbox as (
          select
            shop_id,
            max(received_at) as last_webhook_received_at,
            max(processed_at) as last_webhook_processed_at,
            count(*) filter (where status = 'FAILED')::bigint as webhook_failed_count,
            count(*) filter (where verify_status = 'FAILED')::bigint as webhook_verify_failed_count
          from inbox_events
          where tenant_id = $1
            and shop_id = any($2)
          group by shop_id
        ),
        outbox as (
          select
            (payload->>'shop_id')::uuid as shop_id,
            count(*) filter (where status = 'PENDING')::bigint as webhook_pending_count,
            count(*) filter (where status = 'FAILED')::bigint as webhook_retrying_count,
            min(next_retry_at) filter (where status = 'FAILED') as webhook_next_retry_at,
            min(created_at) filter (where status = 'PENDING') as oldest_pending_at
          from outbox_events
          where tenant_id = $1
            and event_type = 'INBOX_EVENT_RECEIVED'
            and payload ? 'shop_id'
            and (payload->>'shop_id')::uuid = any($2)
          group by (payload->>'shop_id')::uuid
        ),
        dlq as (
          select
            (payload->>'shop_id')::uuid as shop_id,
            count(*) filter (where status = 'PENDING')::bigint as webhook_dlq_count
          from dead_letters
          where tenant_id = $1
            and event_type = 'INBOX_EVENT_RECEIVED'
            and payload ? 'shop_id'
            and (payload->>'shop_id')::uuid = any($2)
          group by (payload->>'shop_id')::uuid
        )
        select
          requested_shops.shop_id,
          inbox.last_webhook_received_at,
          inbox.last_webhook_processed_at,
          coalesce(inbox.webhook_failed_count, 0)::bigint as webhook_failed_count,
          coalesce(inbox.webhook_verify_failed_count, 0)::bigint as webhook_verify_failed_count,
          coalesce(outbox.webhook_pending_count, 0)::bigint as webhook_pending_count,
          coalesce(outbox.webhook_retrying_count, 0)::bigint as webhook_retrying_count,
          coalesce(dlq.webhook_dlq_count, 0)::bigint as webhook_dlq_count,
          outbox.webhook_next_retry_at,
          outbox.oldest_pending_at
        from requested_shops
        left join inbox on inbox.shop_id = requested_shops.shop_id
        left join outbox on outbox.shop_id = requested_shops.shop_id
        left join dlq on dlq.shop_id = requested_shops.shop_id
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(
        shop_ids
            .iter()
            .map(|id| uuid::Uuid::from(*id))
            .collect::<Vec<_>>(),
    )
    .fetch_all(pool)
    .await?;

    for row in rows {
        health_by_shop.insert(
            ShopId(row.shop_id),
            derive_webhook_health_summary(
                row.last_webhook_received_at,
                row.last_webhook_processed_at,
                row.webhook_failed_count,
                row.webhook_verify_failed_count,
                row.webhook_pending_count,
                row.webhook_retrying_count,
                row.webhook_dlq_count,
                row.webhook_next_retry_at,
                row.oldest_pending_at,
            ),
        );
    }

    Ok(health_by_shop)
}

async fn apply_order_item_sku_mappings(
    pool: &PgPool,
    outbox_repo: &OutboxRepo<'_>,
    order: &mut OrderProjection,
) -> anyhow::Result<()> {
    for item in &mut order.items {
        let Some(platform_sku_id) = item.sku_id.clone() else {
            continue;
        };

        let mapped_sku_id = resolve_order_item_sku_mapping(
            pool,
            order.tenant_id,
            order.shop_id,
            order.platform,
            &platform_sku_id,
        )
        .await?;

        match mapped_sku_id {
            Some(mapped) => item.sku_id = Some(mapped),
            None => {
                item.sku_id = None;
                let payload = serde_json::json!({
                    "tenant_id": order.tenant_id,
                    "shop_id": order.shop_id,
                    "platform": order.platform,
                    "platform_sku_id": platform_sku_id,
                    "platform_order_id": order.platform_order_id,
                });
                outbox_repo
                    .enqueue(order.tenant_id, "MAPPING_MISSING", &payload)
                    .await?;
                warn!(
                    tenant_id = %order.tenant_id,
                    shop_id = %order.shop_id,
                    platform = %order.platform,
                    platform_sku_id = %platform_sku_id,
                    platform_order_id = %order.platform_order_id,
                    "sku mapping missing"
                );
            }
        }
    }
    Ok(())
}

async fn resolve_order_item_sku_mapping(
    pool: &PgPool,
    tenant_id: TenantId,
    shop_id: ShopId,
    platform: Platform,
    platform_sku_id: &str,
) -> anyhow::Result<Option<String>> {
    let mapped: Option<uuid::Uuid> = sqlx::query_scalar(
        r#"
        select sku_id
        from channel_sku_mappings
        where tenant_id = $1
          and shop_id = $2
          and platform = $3
          and platform_sku_id = $4
          and status = 'ACTIVE'
        limit 1
        "#,
    )
    .bind(uuid::Uuid::from(tenant_id))
    .bind(uuid::Uuid::from(shop_id))
    .bind(platform.to_string())
    .bind(platform_sku_id)
    .fetch_optional(pool)
    .await?;

    Ok(mapped.map(|id| id.to_string()))
}

fn token_audit_payload(token: &PlatformToken) -> Value {
    serde_json::json!({
        "has_access_token": token.access_token.is_some(),
        "has_refresh_token": token.refresh_token.is_some(),
        "expires_at": token.expires_at,
        "scopes": token.scopes.clone(),
        "token_status": token.token_status.clone(),
        "last_refreshed_at": token.last_refreshed_at,
        "refresh_fail_count": token.refresh_fail_count,
        "last_error": token.last_error.clone(),
        "updated_at": token.updated_at,
    })
}

