async fn fetch_tenant_setting_value(
    pool: &sqlx::PgPool,
    tenant_id: TenantId,
    key: &str,
) -> anyhow::Result<Option<Value>> {
    let repo = SettingsRepo::new(pool);
    let settings = repo
        .list_settings(
            tenant_id,
            SettingListFilters {
                scope_type: Some("TENANT".to_string()),
                scope_id: None,
                key: Some(key.to_string()),
            },
        )
        .await?;
    Ok(settings
        .into_iter()
        .next()
        .map(|setting| setting.value_json))
}

async fn save_tenant_setting_value(
    pool: &sqlx::PgPool,
    tenant_id: TenantId,
    key: &str,
    value: Value,
) -> anyhow::Result<()> {
    let repo = SettingsRepo::new(pool);
    repo.upsert_setting(SettingUpsert {
        tenant_id,
        scope_type: "TENANT".to_string(),
        scope_id: None,
        key: key.to_string(),
        value_json: value,
        expected_version: None,
    })
    .await?;
    Ok(())
}

