fn parse_numeric_setting(value: &Value) -> Option<i64> {
    if let Some(result) = value.as_i64() {
        return Some(result);
    }
    if let Some(obj) = value.as_object() {
        if let Some(result) = obj.get("value").and_then(|item| item.as_i64()) {
            return Some(result);
        }
    }
    None
}

fn parse_bool_setting(value: &Value) -> Option<bool> {
    if let Some(result) = value.as_bool() {
        return Some(result);
    }
    if let Some(obj) = value.as_object() {
        if let Some(result) = obj.get("value").and_then(|item| item.as_bool()) {
            return Some(result);
        }
    }
    None
}

fn parse_string_setting(value: &Value) -> Option<String> {
    if let Some(result) = value.as_str() {
        let trimmed = result.trim();
        if !trimmed.is_empty() {
            return Some(trimmed.to_string());
        }
    }
    if let Some(obj) = value.as_object() {
        if let Some(result) = obj.get("value").and_then(|item| item.as_str()) {
            let trimmed = result.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
    }
    None
}

fn inventory_error_response(err: anyhow::Error) -> (StatusCode, Json<ErrorResponse>) {
    if let Some(inv) = err.downcast_ref::<InventoryError>() {
        return match inv {
            InventoryError::InsufficientAvailable { .. } => error_response(
                StatusCode::CONFLICT,
                "inventory_insufficient",
                "insufficient inventory",
            ),
            InventoryError::InsufficientFrozen { .. } => error_response(
                StatusCode::CONFLICT,
                "inventory_frozen_insufficient",
                "insufficient frozen inventory",
            ),
            InventoryError::ReservationNotFound => error_response(
                StatusCode::NOT_FOUND,
                "reservation_not_found",
                "reservation not found",
            ),
            InventoryError::ReservationNotActive => error_response(
                StatusCode::CONFLICT,
                "reservation_not_active",
                "reservation not active",
            ),
            InventoryError::ReservationMismatch => error_response(
                StatusCode::BAD_REQUEST,
                "reservation_mismatch",
                "reservation mismatch",
            ),
        };
    }

    error_response(
        StatusCode::INTERNAL_SERVER_ERROR,
        "internal_error",
        &err.to_string(),
    )
}

